.clrw{position:relative;display:inline-flex;align-items:center}
.clrw>input{padding-right:28px;width:100%}
.clrx{position:absolute;right:4px;top:50%;transform:translateY(-50%);width:22px;height:22px;border:0;border-radius:50%;background:transparent;color:#8a94a0;font-size:16px;line-height:22px;padding:0;cursor:pointer;display:none}
.clrx:hover{background:#e9edf2;color:#333}
.clrw.has .clrx{display:block}
input[type=search]::-webkit-search-cancel-button{display:none}
/** 文字輸入框右側加「×」一鍵清除（清除後觸發 input 事件，篩選立即更新） */
function addClear(inp) {
  if (!inp || inp.parentNode.classList.contains('clrw')) return;
  const w = document.createElement('span'); w.className = 'clrw'; w.style.minWidth = inp.style.minWidth || '';
  inp.parentNode.insertBefore(w, inp); w.appendChild(inp);
  const x = document.createElement('button'); x.type = 'button'; x.className = 'clrx'; x.title = '清除'; x.textContent = '×'; w.appendChild(x);
  const upd = () => w.classList.toggle('has', !!inp.value);
  inp.addEventListener('input', upd); upd();
  x.onclick = () => { inp.value = ''; inp.dispatchEvent(new Event('input', { bubbles: true })); inp.focus(); };
  // 程式改值（例如重設篩選）時也更新 × 顯示
  const d = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
  Object.defineProperty(inp, 'value', { get() { return d.get.call(this); }, set(v) { d.set.call(this, v); upd(); } });
}
addClear($('fKey'));
